CREATE TABLE campaigns(id uuid PRIMARY KEY, name text NOT NULL, mode text NOT NULL CHECK(mode IN ('PROGRESSIVE','PREDICTIVE')), status text NOT NULL DEFAULT 'STOPPED', provider text NOT NULL CHECK(provider IN ('A','B')), max_active int NOT NULL CHECK(max_active BETWEEN 1 AND 10000), risk_limit double precision NOT NULL CHECK(risk_limit BETWEEN 0 AND 0.1), answer_rate double precision NOT NULL DEFAULT 0.5, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE agents(id uuid PRIMARY KEY, name text NOT NULL, campaign_id uuid NOT NULL REFERENCES campaigns, state text NOT NULL DEFAULT 'OFFLINE' CHECK(state IN ('OFFLINE','AVAILABLE','RESERVED','DIALING','CONNECTED','WRAP_UP','PAUSED')), last_heartbeat timestamptz NOT NULL DEFAULT now(), current_call_id uuid, reserved_at timestamptz, reservation_expiry timestamptz, version bigint NOT NULL DEFAULT 0);
CREATE TABLE borrowers(id uuid PRIMARY KEY, name text NOT NULL);
CREATE TABLE campaign_borrowers(campaign_id uuid REFERENCES campaigns, borrower_id uuid REFERENCES borrowers, status text NOT NULL DEFAULT 'ELIGIBLE', PRIMARY KEY(campaign_id,borrower_id));
CREATE TABLE calls(id uuid PRIMARY KEY, campaign_id uuid NOT NULL REFERENCES campaigns, borrower_id uuid NOT NULL REFERENCES borrowers, agent_id uuid REFERENCES agents, provider text NOT NULL, provider_call_id text, state text NOT NULL CHECK(state IN ('QUEUED','RESERVED','INITIATED','RINGING','ANSWERED','CONNECTED','COMPLETED','FAILED','CANCELLED')), idempotency_key text NOT NULL UNIQUE, answered_at timestamptz, connected_at timestamptz, ended_at timestamptz, reason text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
ALTER TABLE agents ADD CONSTRAINT agent_current_call_fk FOREIGN KEY(current_call_id) REFERENCES calls DEFERRABLE INITIALLY DEFERRED;
CREATE UNIQUE INDEX one_active_call_per_agent ON calls(agent_id) WHERE state NOT IN ('COMPLETED','FAILED','CANCELLED');
CREATE UNIQUE INDEX one_active_call_per_borrower ON calls(borrower_id) WHERE state NOT IN ('COMPLETED','FAILED','CANCELLED');
CREATE INDEX calls_campaign_state ON calls(campaign_id,state);
CREATE INDEX agent_allocation ON agents(campaign_id,state,last_heartbeat);
CREATE TABLE reservations(id uuid PRIMARY KEY, call_id uuid NOT NULL UNIQUE REFERENCES calls, agent_id uuid REFERENCES agents, borrower_id uuid NOT NULL REFERENCES borrowers, expires_at timestamptz NOT NULL, released_at timestamptz);
CREATE TABLE call_events(provider text NOT NULL, event_id text NOT NULL, call_id uuid NOT NULL REFERENCES calls, event_type text NOT NULL, outcome text NOT NULL DEFAULT 'RECEIVED', received_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(provider,event_id));
CREATE TABLE provider_dispatches(call_id uuid PRIMARY KEY REFERENCES calls, idempotency_key text UNIQUE NOT NULL, status text NOT NULL DEFAULT 'PENDING', attempts int NOT NULL DEFAULT 0, lease_until timestamptz, last_error text);
CREATE TABLE outbox_events(id uuid PRIMARY KEY, call_id uuid NOT NULL UNIQUE REFERENCES calls, status text NOT NULL DEFAULT 'PENDING', lease_until timestamptz, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE pacing_decisions(id uuid PRIMARY KEY, campaign_id uuid NOT NULL REFERENCES campaigns, mode text NOT NULL, requested int NOT NULL, probability double precision NOT NULL, explanation text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE safety_decisions(id uuid PRIMARY KEY REFERENCES pacing_decisions, campaign_id uuid NOT NULL REFERENCES campaigns, action text NOT NULL, approved int NOT NULL, capacity int NOT NULL, exposure int NOT NULL, risk double precision NOT NULL, reason text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE simulation_runs(id uuid PRIMARY KEY, config jsonb NOT NULL, result jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE simulation_metrics(id bigserial PRIMARY KEY, run_id uuid NOT NULL REFERENCES simulation_runs, mode text NOT NULL, metrics jsonb NOT NULL);
-- Durable mock provider boundary: survives application worker crashes.
CREATE TABLE mock_provider_calls(id text PRIMARY KEY, provider text NOT NULL, idempotency_key text NOT NULL UNIQUE, call_id uuid NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), answer_at timestamptz NOT NULL, finish_at timestamptz NOT NULL, will_answer boolean NOT NULL, fail boolean NOT NULL, answered_sent boolean NOT NULL DEFAULT false, completed_sent boolean NOT NULL DEFAULT false);
CREATE TABLE provider_health(provider text PRIMARY KEY, outage boolean NOT NULL DEFAULT false, failures int NOT NULL DEFAULT 0, circuit_until timestamptz, latency_ms int NOT NULL, failure_rate double precision NOT NULL, seed bigint NOT NULL DEFAULT 42);
INSERT INTO provider_health(provider,latency_ms,failure_rate) VALUES('A',100,0.01),('B',600,0.12);
